<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; require_login();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
$stmt=$pdo->prepare("SELECT o.*,s.name AS seller_name,s.email AS seller_email,b.name AS buyer_account_name FROM orders o JOIN users s ON s.id=o.seller_id JOIN users b ON b.id=o.buyer_id WHERE o.id=? AND (o.buyer_id=? OR o.seller_id=? OR ?='admin') LIMIT 1"); $role=current_user()['role']; $stmt->execute([$id?:0,(int)current_user()['id'],(int)current_user()['id'],$role]); $o=$stmt->fetch();
if(!$o){http_response_code(404);exit('Order not found.');}
$pageTitle='Order #'.(int)$o['id']; require __DIR__.'/includes/header.php';
?>
<section class="container order-page"><div class="section-heading"><div><span class="eyebrow">Order details</span><h2>Order #<?= (int)$o['id'] ?></h2><p><?= e($o['created_at']) ?></p></div><strong class="price">₹<?= number_format((float)$o['amount'],2) ?></strong></div><article class="order-card"><h3><?= e($o['book_title']) ?></h3><div class="order-badges"><span class="status status-pending">Order: <?= e(ucfirst($o['order_status'])) ?></span><span class="status <?= $o['payment_status']==='paid'?'status-approved':($o['payment_status']==='failed'?'status-rejected':'status-pending') ?>">Payment: <?= e(ucfirst($o['payment_status'])) ?></span></div><p><strong>Payment method:</strong> <?= $o['payment_method']==='cod'?'Cash on Delivery / pay seller':'Razorpay online payment' ?></p><p><strong>Buyer:</strong> <?= e($o['buyer_name']) ?> · <?= e($o['buyer_phone']) ?> · <a href="mailto:<?= e($o['buyer_email']) ?>"><?= e($o['buyer_email']) ?></a></p><p><strong>Seller:</strong> <?= e($o['seller_name']) ?> · <a href="mailto:<?= e($o['seller_email']) ?>"><?= e($o['seller_email']) ?></a></p><p><strong>Delivery address:</strong><br><?= nl2br(e($o['delivery_address'])) ?></p><p><strong>Delivery note:</strong> <?= e($o['delivery_note'] ?: 'None') ?></p><div class="notice">Buyer and seller arrange delivery, delivery charges, and handover directly. BookBazaar does not provide shipping in this version.</div><a class="button button-light" href="<?= (int)$o['buyer_id']===(int)current_user()['id']?'my-orders.php':'my-sales.php' ?>">Back to orders</a></article></section>
<?php require __DIR__.'/includes/footer.php'; ?>
